package Lec_07;

public class Array_Demo {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int[] arr= new int[5];
		System.out.println(arr);
		
		arr[1]=10;
		arr[2]=20;
		arr[3]=30;
		arr[4]=-40;
		int i=0;
		while(i<arr.length) {
		System.out.println(arr[i]);	
		i++;
		}
	
		
	}

}
